module find_max_area (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] m,\n    input [7:0] a [0:7],\n    input [7:0] b [0:7],\n    input [31:0] x,\n    output reg [15:0] result,\n    output reg done\n);\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] PREFIX_A = 3'd2;\n    localparam [2:0] MIN_ROW = 3'd3;\n    localparam [2:0] PREFIX_B = 3'd4;\n    localparam [2:0] MIN_COL = 3'd5;\n    localparam [2:0] MAX_AREA = 3'd6;\n    localparam [2:0] DONE_ST = 3'd7;\n\n    reg [2:0] state, next_state;\n    reg [11:0] prefix_sum_a [0:7];\n    reg [11:0] prefix_sum_b [0:7];\n    reg [11:0] min_row [0:7];\n    reg [11:0] min_col [0:7];\n    reg [7:0] cycle_count;\n    reg [3:0] i_reg, l_len, idx;\n    reg [3:0] l1_reg, l2_reg;\n    reg [15:0] max_area_reg;\n    localparam [11:0] MAX_SUM = 12'hFFF;\n    localparam [7:0] MAX_CYCLES = 8'd150;\n\n    // Temp variables\n    reg [11:0] sum_temp;\n    reg [31:0] temp_product;\n    reg [7:0] current_area;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            for (i = 0; i < 8; i = i + 1) begin\n                prefix_sum_a[i] <= 12'd0;\n                prefix_sum_b[i] <= 12'd0;\n                min_row[i] <= MAX_SUM;\n                min_col[i] <= MAX_SUM;\n            end\n            i_reg <= 4'd0;\n            l_len <= 4'd0;\n            idx <= 4'd0;\n            cycle_count <= 8'd0;\n            l1_reg <= 4'd0;\n            l2_reg <= 4'd0;\n            max_area_reg <= 16'd0;\n            result <= 16'd0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        next_state <= INIT;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                INIT: begin\n                    for (i = 0; i < 8; i = i + 1) begin\n                        prefix_sum_a[i] <= 12'd0;\n                        prefix_sum_b[i] <= 12'd0;\n                        min_row[i] <= MAX_SUM;\n                        min_col[i] <= MAX_SUM;\n                    end\n                    i_reg <= 4'd0;\n                    l_len <= 4'd1;\n                    idx <= 4'd0;\n                    max_area_reg <= 16'd0;\n                    next_state <= PREFIX_A;\n                end\n\n                PREFIX_A: begin\n                    if (i_reg < n) begin\n                        if (i_reg == 4'd0) begin\n                            prefix_sum_a[i_reg] <= a[i_reg];\n                        end else begin\n                            prefix_sum_a[i_reg] <= prefix_sum_a[i_reg-1] + a[i_reg];\n                        end\n                        i_reg <= i_reg + 1;\n                    end else begin\n                        i_reg <= 4'd0;\n                        next_state <= MIN_ROW;\n                    end\n                end\n\n                MIN_ROW: begin\n                    if (l_len <= n) begin\n                        if (idx <= (n - l_len)) begin\n                            if (idx == 4'd0) begin\n                                sum_temp = prefix_sum_a[l_len - 1];\n                            end else begin\n                                sum_temp = prefix_sum_a[idx + l_len - 1] - prefix_sum_a[idx-1];\n                            end\n                            if (sum_temp < min_row[l_len-1]) begin\n                                min_row[l_len-1] <= sum_temp;\n                            end\n                            idx <= idx + 1;\n                        end else begin\n                            idx <= 4'd0;\n                            l_len <= l_len + 1;\n                        end\n                    end else begin\n                        l_len <= 4'd1;\n                        idx <= 4'd0;\n                        i_reg <= 4'd0;\n                        next_state <= PREFIX_B;\n                    end\n                end\n\n                PREFIX_B: begin\n                    if (i_reg < m) begin\n                        if (i_reg == 4'd0) begin\n                            prefix_sum_b[i_reg] <= b[i_reg];\n                        end else begin\n                            prefix_sum_b[i_reg] <= prefix_sum_b[i_reg-1] + b[i_reg];\n                        end\n                        i_reg <= i_reg + 1;\n                    end else begin\n                        i_reg <= 4'd0;\n                        next_state <= MIN_COL;\n                    end\n                end\n\n                MIN_COL: begin\n                    if (l_len <= m) begin\n                        if (idx <= (m - l_len)) begin\n                            if (idx == 4'd0) begin\n                                sum_temp = prefix_sum_b[l_len - 1];\n                            end else begin\n                                sum_temp = prefix_sum_b[idx + l_len - 1] - prefix_sum_b[idx-1];\n                            end\n                            if (sum_temp < min_col[l_len-1]) begin\n                                min_col[l_len-1] <= sum_temp;\n                            end\n                            idx <= idx + 1;\n                        end else begin\n                            idx <= 4'd0;\n                            l_len <= l_len + 1;\n                        end\n                    end else begin\n                        l_len <= 4'd0;\n                        idx <= 4'd0;\n                        l1_reg <= 4'd1;\n                        l2_reg <= 4'd1;\n                        next_state <= MAX_AREA;\n                    end\n                end\n\n                MAX_AREA: begin\n                    if (l1_reg <= n) begin\n                        if (l2_reg <= m) begin\n                            temp_product = min_row[l1_reg - 1] * min_col[l2_reg - 1];\n                            if (temp_product <= x) begin\n                                current_area = l1_reg * l2_reg;\n                                if (current_area > max_area_reg) begin\n                                    max_area_reg <= current_area;\n                                end\n                            end\n                            if (l2_reg < m) begin\n                                l2_reg <= l2_reg + 1;\n                            end else begin\n                                l2_reg <= 4'd1;\n                                l1_reg <= l1_reg + 1;\n                            end\n                        end\n                    end else begin\n                        next_state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    result <= max_area_reg;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: begin\n                    next_state <= IDLE;\n                end\n            endcase\n\n            // Timeout guard\n            if (cycle_count >= MAX_CYCLES) begin\n                next_state <= DONE_ST;\n            end\n        end\n    end\nendmodule